LEVEL = 1
CFG = {1: 3, 2: 5, 3: 8}
N = CFG[LEVEL]
import hashlib
def seal(prev, payload):
    return hashlib.sha256((prev + payload).encode()).hexdigest()
chain, prev = [], "GENESIS"
for i in range(N):
    prev = seal(prev, "state-%d" % i); chain.append(prev)
ok = True
prev = "GENESIS"
for i, h in enumerate(chain):
    prev = seal(prev, "state-%d" % i)
    if prev != h: ok = False
tampered = list(chain); tampered[1] = "0" * 64
prev = "GENESIS"; tamper_found = False
for i, h in enumerate(tampered):
    prev = seal(prev, "state-%d" % i)
    if prev != h: tamper_found = True
print("chain valid:", ok, "| tamper detected:", tamper_found)

