LEVEL = 1
CFG = {1: 4, 2: 6, 3: 9}
M = CFG[LEVEL]
ckpt = {"f%d" % i: i * 10 for i in range(M)}
live = dict(ckpt); live["f1"] = 999; live["f%d" % (M - 1)] = -1
diffs = []
for k in ckpt:
    if ckpt[k] != live[k]:
        kind = "destructive" if live[k] < 0 else ("risky" if abs(live[k] - ckpt[k]) > 100 else "safe")
        diffs.append((k, ckpt[k], live[k], kind))
for k, a, b, kind in diffs:
    print("%s: %s -> %s [%s]" % (k, a, b, kind))
print("total changes:", len(diffs))

