LEVEL = 1
CFG = {1: 5, 2: 8, 3: 11}
N = CFG[LEVEL]
nodes = {0: None}
for i in range(1, N):
    nodes[i] = i - 1 if i % 3 else max(0, i - 2)  # occasional branch
def ancestry(n):
    path = []
    while n is not None:
        path.append(n); n = nodes[n]
    return path
tip = N - 1
print("nodes:", N, "| ancestry of tip", tip, ":", ancestry(tip))

